import React, { useState, useEffect, useRef } from 'react';
import EmergencyInfoPage from './EmergencyInfoPage'; 

const API_URL = 'http://127.0.0.1:5000/api/emergency_status';
// We need this endpoint to set the status
const TOGGLE_URL = 'http://127.0.0.1:5000/api/toggle_emergency'; 
const POLLING_INTERVAL = 2000; 

function EmergencyMonitor() {
  const [emergencyDetected, setEmergencyDetected] = useState(false);
  const [loading, setLoading] = useState(true);
  const [speechStatus, setSpeechStatus] = useState("Initializing voice monitor...");
  
  // Use a ref to hold the Recognition instance
  const recognitionRef = useRef(null);

  // Function to send the signal to the backend
  const triggerEmergencyAPI = async () => {
    try {
      setSpeechStatus("🚨 Voice command detected. Sending emergency signal...");
      const response = await fetch(TOGGLE_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: true }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      // Since the polling is running, it will pick up the change soon
      console.log("✅ Emergency signal sent successfully.");
      setSpeechStatus("✅ Signal sent. Waiting for confirmation via poll.");

    } catch (error) {
      console.error("Failed to send emergency trigger.", error);
      setSpeechStatus(`❌ Failed to send signal: ${error.message}`);
    }
  };

  // Function to fetch the status from the Python backend (Polling)
  const checkEmergencyStatus = async () => {
    // ... (Your existing checkEmergencyStatus function remains here)
    try {
      const response = await fetch(API_URL);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      
      if (data.detected === true && !emergencyDetected) {
        console.log("🚨 Emergency signal received from backend!");
        setEmergencyDetected(true);
      }

    } catch (error) {
      console.error("Failed to fetch emergency status. Is the Python server running?", error);
    } finally {
      setLoading(false);
    }
  };

  // --- VOICE MONITOR SETUP ---
  useEffect(() => {
    if (!('webkitSpeechRecognition' in window)) {
        setSpeechStatus("❌ Browser does not support Web Speech API. Voice trigger disabled.");
        return;
    }
    
    // Create the recognition instance
    const recognition = new window.webkitSpeechRecognition();
    recognition.continuous = true; // Keep listening
    recognition.interimResults = false; // Only get final results
    recognition.lang = 'en-US'; 
    recognitionRef.current = recognition;

    recognition.onstart = () => {
        setSpeechStatus("🎤 Listening for 'help' command...");
    };

    recognition.onerror = (event) => {
        console.error('Speech recognition error:', event);
        if (event.error === 'not-allowed') {
            setSpeechStatus("❌ Microphone access denied. Please allow access.");
        } else {
            setSpeechStatus(`⚠️ Error (${event.error}). Restarting...`); // Log the error type
        }
    };

    // 🌟 ADDED: Handler for when service times out due to silence
    recognition.onnospeech = () => {
        console.warn("DEBUG: Heard no speech before timeout.");
        setSpeechStatus("⚠️ Timed out. Restarting listening...");
    };
    
    // 🌟 MODIFIED: Robust restart logic
    recognition.onend = () => {
        console.log("DEBUG: Recognition service ended. Restarting...");
        // Automatically restart listening after the service stops
        if (!emergencyDetected) { 
            try {
                recognition.start();
            } catch (e) {
                console.error("FATAL DEBUG: Restart attempt failed!", e);
                setSpeechStatus("❌ Failed to maintain listening service.");
            }
        }
    };

    recognition.onresult = (event) => {
      const last = event.results.length - 1;
      const command = event.results[last][0].transcript.trim().toLowerCase();
      console.log('Voice Input:', command);

      // --- CRITICAL: Check for the keyword ---
      if (command.includes('help')) {
        setSpeechStatus("✅ 'HELP' detected!");
        // Stop listening to prevent re-triggering
        recognition.stop(); 
        triggerEmergencyAPI(); 
      }
    };

    // Start listening on mount
    try {
        recognition.start();
    } catch (e) {
        console.warn("Recognition already started or failed to start:", e);
    }
    
    // Cleanup function for speech recognition
    return () => {
        recognition.stop();
    };
  }, [emergencyDetected]); // Rerun effect if emergencyDetected changes

  // --- POLLING SETUP (Your existing useEffect) ---
  useEffect(() => {
    // Run the check immediately on mount
    checkEmergencyStatus();

    // Set up the interval for continuous polling
    const intervalId = setInterval(checkEmergencyStatus, POLLING_INTERVAL);

    // Clean up the interval when the component unmounts
    return () => {
      clearInterval(intervalId);
    };
  }, []); // Run only once for the polling loop

  // --- RENDERING LOGIC ---
  if (loading) {
    return <div>Checking for emergency status...</div>;
  }

  if (emergencyDetected) {
    // Render the dedicated emergency page if an emergency is detected
    return <EmergencyInfoPage />;
  }
  
  // Render the default view with monitoring status
  return (
    <div>
      <h2>System Status: OK ✅</h2>
      <p>Monitoring backend for emergency signal every {POLLING_INTERVAL / 1000} seconds...</p>
      <hr/>
      <h3>Voice Trigger Status</h3>
      <p style={{ fontWeight: 'bold' }}>{speechStatus}</p>
      <p>Try saying "help" out loud.</p>
    </div>
  );
}

export default EmergencyMonitor;
